      />
      <Stack.Screen
        name="AddValueEvent"
        component={AddValueEventScreen}
        options={{
          presentation: "modal",
          headerTitle: "Log Value Event",
        }}
      />
      <Stack.Screen
        name="AddRealityIncome"
        component={AddRealityIncomeScreen}
        options={{
          presentation: "modal",
          headerTitle: "Reality Income",
        }}
      />
      <Stack.Screen
        name="Calendar"
        component={CalendarScreen}
        options={{
          headerTitle: "History",
        }}
      />
    </Stack.Navigator>
  );
}

