                </View>
              </View>

              <ThemedText style={[styles.inputLabel, { color: colors.text }]}>
                Recurrence
              </ThemedText>
              <View style={styles.recurrenceSelector}>
                {RECURRENCE_OPTIONS.map((option) => (
                  <Pressable
                    key={option.id}
                    style={[
                      styles.recurrenceOption,
