                      ]}
                    >
                      {option.label}
                    </ThemedText>
                  </Pressable>
                ))}
              </View>

              <View style={styles.row}>
                <View style={styles.halfWidth}>
                  <StyledInput
                    label="Default Units"
                    value={formDefaultUnits}
                    onChangeText={setFormDefaultUnits}
